import{_ as t,o as s,c as e,a2 as i}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"baud","description":"","frontmatter":{},"headers":[],"relativePath":"notes/hardware/serial/baud.md","filePath":"notes/hardware/serial/baud.md"}'),d={name:"notes/hardware/serial/baud.md"};function r(n,a,l,o,p,h){return s(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="baud" tabindex="-1">baud <a class="header-anchor" href="#baud" aria-label="Permalink to &quot;baud&quot;">​</a></h1><h2 id="_1-divisor的含义" tabindex="-1">1. divisor的含义 <a class="header-anchor" href="#_1-divisor的含义" aria-label="Permalink to &quot;1. divisor的含义&quot;">​</a></h2><p><code>divisor</code>是写入8250兼容UART（PC兼容串口）**除数锁存寄存器（Divisor Latch Registers，DLL/DLM）**的分频值。UART内部有一个固定频率的基准时钟，通过该分频值分频后产生实际的波特率时钟。</p><h2 id="_2-三者的数学关系" tabindex="-1">2. 三者的数学关系 <a class="header-anchor" href="#_2-三者的数学关系" aria-label="Permalink to &quot;2. 三者的数学关系&quot;">​</a></h2><p>8250 UART的波特率产生规则：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>波特率时钟 = 基准时钟 / (divisor × 16)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>其中：</p><ul><li><strong>16</strong>：UART对每位采样16次（16x过采样），这是8250的固定设计；</li><li><strong>基准时钟</strong>：PC兼容串口的标准基准频率为 <strong>1,843,200 Hz</strong>（1.8432 MHz）。</li></ul><p>由此推导：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>baud = 1843200 / (divisor × 16) = 115200 / divisor</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>反解即得代码中的公式：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">divisor </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 115200</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> /</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> baud;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>所以代码中的<strong>115200并不是一个波特率，而是 1,843,200 / 16 的商</strong>，即“分频值为1时对应的波特率”，是硬件常数换算的结果。</p><h2 id="_3-举例验证" tabindex="-1">3. 举例验证 <a class="header-anchor" href="#_3-举例验证" aria-label="Permalink to &quot;3. 举例验证&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目标baud</th><th>divisor = 115200/baud</th><th>说明</th></tr></thead><tbody><tr><td>115200</td><td>1</td><td>分频值1，即最大波特率</td></tr><tr><td>57600</td><td>2</td><td></td></tr><tr><td>38400</td><td>3</td><td></td></tr><tr><td>19200</td><td>6</td><td></td></tr><tr><td>9600</td><td>12</td><td>传统默认值</td></tr><tr><td>9600（实际）</td><td>12</td><td>1843200/(12×16) = 9600，精确</td></tr></tbody></table><p>注意：若baud不能整除115200（如baud=14400，divisor=8），则实际波特率与目标存在偏差；8250允许一定容差（约±3%以内可正常通信）。</p>',16)])])}const b=t(d,[["render",r]]);export{u as __pageData,b as default};
